#include <stdio.h>

int main(void) {
    int N, Q;
    scanf("%d %d", &N, &Q);

    int a[50][50], b[50][50];
    char line[55];

    for (int i = 0; i < N; i++) {
        scanf("%s", line);
        for (int j = 0; j < N; j++) {
            a[i][j] = line[j] - '0';
        }
    }

    for (int step = 0; step < Q; step++) {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                int cnt = 0;

                for (int di = -1; di <= 1; di++) {
                    for (int dj = -1; dj <= 1; dj++) {
                        if (di == 0 && dj == 0) continue;

                        int ni = i + di;
                        int nj = j + dj;

                        if (ni >= 0 && ni < N && nj >= 0 && nj < N) {
                            cnt += a[ni][nj];
                        }
                    }
                }

                if (a[i][j] == 1) {
                    if (cnt == 2 || cnt == 3) b[i][j] = 1;
                    else b[i][j] = 0;
                } else {
                    if (cnt == 3) b[i][j] = 1;
                    else b[i][j] = 0;
                }
            }
        }

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                a[i][j] = b[i][j];
            }
        }
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            putchar(a[i][j] ? '1' : '0');
        }
        putchar('\n');
    }

    return 0;
}
